import calendar

import pytest

from datetime import date

from dispatch.case import scheduled


@pytest.mark.parametrize("day", range(1, 8))
def test_is_reminder_day(monkeypatch, day):
    # 2025-08-11 is a Monday, so 2025-08-11 + (day - 1) covers every weekday
    today = date(2025, 8, 10 + day)

    class FrozenDate(date):
        @classmethod
        def today(cls):
            return today

    monkeypatch.setattr(scheduled, "date", FrozenDate)

    assert scheduled._is_reminder_day() is (today.weekday() == calendar.MONDAY)


def test_is_reminder_day_on_monday(monkeypatch):
    class FrozenMonday(date):
        @classmethod
        def today(cls):
            return date(2025, 8, 18)

    monkeypatch.setattr(scheduled, "date", FrozenMonday)

    assert scheduled._is_reminder_day() is True

